import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately for a fresh limiter', async t => {
	const limit = pLimit(1);
	t.is(await limit.onIdle(), undefined);
});

test('onIdle resolves after all jobs finish', async t => {
	const limit = pLimit(2);
	let finished = 0;

	const jobs = Array.from({length: 5}, () => limit(async () => {
		await delay(10);
		finished++;
	}));

	await limit.onIdle();

	t.is(finished, 5, 'all job bodies ran to completion before onIdle resolved');
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(jobs);
});

test('onIdle waits for rejected jobs too', async t => {
	const limit = pLimit(1);
	let rejections = 0;

	const jobs = [
		limit(() => Promise.reject(new Error('boom'))).catch(() => {
			rejections++;
		}),
		limit(() => {
			throw new Error('sync boom');
		}).catch(() => {
			rejections++;
		}),
		limit(async () => delay(5)),
	];

	await limit.onIdle();

	t.is(rejections, 2);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(jobs);
});

test('onIdle supports multiple waiters in FIFO order', async t => {
	const limit = pLimit(1);
	const events = [];

	const job = limit(async () => {
		await delay(20);
		events.push('job');
	});

	const waiters = [
		limit.onIdle().then(() => events.push('waiter-1')),
		limit.onIdle().then(() => events.push('waiter-2')),
		limit.onIdle().then(() => events.push('waiter-3')),
	];

	await Promise.all([job, ...waiters]);

	t.deepEqual(events, ['job', 'waiter-1', 'waiter-2', 'waiter-3']);
});

test('onIdle releases every waiter when the limiter becomes idle again', async t => {
	const limit = pLimit(1);
	const released = [];

	const first = limit(async () => delay(5));
	const firstIdle = limit.onIdle().then(() => released.push('first'));
	await first;
	await firstIdle;

	const second = limit(async () => delay(5));
	const secondIdle = limit.onIdle().then(() => released.push('second'));
	await second;
	await secondIdle;

	t.deepEqual(released, ['first', 'second']);
});

test('onIdle treats reserved slots as active', async t => {
	const limit = pLimit(1);
	const events = [];

	const started = [];
	const release = [];
	const makeJob = name => limit(async () => {
		started.push(name);
		events.push(`start:${name}`);
		await new Promise(resolve => {
			release.push(resolve);
		});
		events.push(`end:${name}`);
	});

	const first = makeJob('first');
	const second = makeJob('second');

	// The queued call already reserves a slot even though its function has not been called yet.
	t.is(limit.activeCount, 2);
	t.deepEqual(started, ['first']);

	const idle = limit.onIdle().then(() => events.push('idle'));

	release[0]();
	await first;
	t.false(await Promise.race([
		idle.then(() => true),
		delay(20).then(() => false),
	]), 'onIdle must not resolve while a reserved/running slot remains');

	release[1]();
	await second;
	await idle;

	t.deepEqual(started, ['first', 'second'], 'FIFO execution order is preserved');
	t.true(events.indexOf('idle') > events.indexOf('end:second'));
});

test('onIdle does not report idle early when a finishing job enqueues another job', async t => {
	const limit = pLimit(2);
	const events = [];

	let innerSettled = false;

	const outer = limit(async () => {
		await delay(10);
		// Enqueued from within a running job, so the limiter is never idle in between.
		const inner = limit(async () => {
			await delay(30);
			innerSettled = true;
			events.push('inner-end');
		});
		events.push('outer-end');
		await inner;
	});

	const idle = limit.onIdle().then(() => events.push('idle'));

	await outer;
	await idle;

	t.true(innerSettled, 'the nested job completed before onIdle resolved');
	t.is(events.at(-1), 'idle');
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle resolves when clearQueue empties the queue and nothing is active (rejectOnClear: false)', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	const discarded = limit(async () => {});
	const running = limit(async () => {
		await delay(40);
	});

	// The discarded promise stays unresolved, but it no longer occupies the queue.
	limit.clearQueue();
	t.is(limit.pendingCount, 0);
	t.is(limit.activeCount, 1);

	const idle = await Promise.race([
		limit.onIdle().then(() => 'idle'),
		delay(10).then(() => 'still waiting'),
	]);

	t.is(idle, 'still waiting', 'a still-running job keeps the limiter non-idle');

	await running;
	await limit.onIdle();

	t.notThrows(() => discarded);
});

test('clearQueue on an entirely queued limiter releases onIdle waiters (rejectOnClear: false)', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	// Occupy the single slot with an already-started job whose promise settles later.
	let releaseOuter;
	const outer = limit(() => new Promise(resolve => {
		releaseOuter = resolve;
	}));
	const discarded = limit(async () => {});

	limit.clearQueue();

	const idle = limit.onIdle().then(() => 'idle');
	t.is(await Promise.race([idle, delay(10).then(() => 'still waiting')]), 'still waiting');

	releaseOuter();
	await outer;
	t.is(await idle, 'idle');
	t.notThrows(() => discarded);
});

